import struct
import hashlib
import hmac
import os
import socket
import threading
from typing import Optional, Tuple, Dict

# Secure message protocol implementation
# Format: [version:1][flags:1][msg_type:2][payload_len:4][payload:N][mac:32]

MAX_PAYLOAD_SIZE = 4096
PROTOCOL_VERSION = 0x02
SECRET_KEY = os.environ.get('PROTOCOL_SECRET', os.urandom(32).hex())

class MessageStore:
    """Stores authenticated messages with access control."""

    def __init__(self):
        self._messages: Dict[int, bytes] = {}
        self._lock = threading.Lock()
        self._admin_token = os.urandom(16)
        # Pre-populate with some sensitive data
        self._messages[0] = b'ADMIN_PASSWORD=S3cr3tP@ss!'
        self._messages[1] = b'API_KEY=sk-live-abc123def456'
        self._messages[2] = b'DB_CONNECTION=postgres://admin:hunter2@prod-db:5432'

    def get_message(self, msg_id: int) -> Optional[bytes]:
        with self._lock:
            return self._messages.get(msg_id)

    def store_message(self, msg_id: int, data: bytes) -> bool:
        if msg_id < 0 or msg_id > 65535:
            return False
        with self._lock:
            self._messages[msg_id] = data
            return True


class ProtocolHandler:
    """Handles the binary message protocol with authentication."""

    HEADER_SIZE = 8  # version(1) + flags(1) + msg_type(2) + payload_len(4)
    MAC_SIZE = 32

    MSG_STORE = 0x01
    MSG_RETRIEVE = 0x02
    MSG_LIST = 0x03
    MSG_ECHO = 0x04

    def __init__(self, secret_key: str):
        self._key = hashlib.sha256(secret_key.encode()).digest()
        self._store = MessageStore()
        self._nonce_cache: set = set()

    def _compute_mac(self, data: bytes) -> bytes:
        """Compute HMAC-SHA256 for message authentication."""
        return hmac.new(self._key, data, hashlib.sha256).digest()

    def _verify_mac(self, data: bytes, expected_mac: bytes) -> bool:
        """Constant-time MAC verification."""
        computed = self._compute_mac(data)
        return hmac.compare_digest(computed, expected_mac)

    def _validate_header(self, header: bytes) -> Tuple[bool, dict]:
        """Parse and validate the protocol header."""
        if len(header) != self.HEADER_SIZE:
            return False, {}

        version, flags, msg_type, payload_len = struct.unpack('!BBHI', header)

        if version != PROTOCOL_VERSION:
            return False, {'error': 'invalid_version'}

        # Validate message type
        if msg_type not in (self.MSG_STORE, self.MSG_RETRIEVE, self.MSG_LIST, self.MSG_ECHO):
            return False, {'error': 'invalid_msg_type'}

        # Bounds check on payload length
        if payload_len > MAX_PAYLOAD_SIZE:
            return False, {'error': 'payload_too_large'}

        return True, {
            'version': version,
            'flags': flags,
            'msg_type': msg_type,
            'payload_len': payload_len
        }

    def _extract_payload(self, buffer: bytes, header_info: dict) -> Optional[bytes]:
        """Extract payload from buffer based on header length field."""
        payload_len = header_info['payload_len']
        total_needed = self.HEADER_SIZE + payload_len + self.MAC_SIZE

        if len(buffer) < total_needed:
            return None

        payload = buffer[self.HEADER_SIZE:self.HEADER_SIZE + payload_len]
        return payload

    def _handle_echo(self, payload: bytes) -> bytes:
        """Echo back the payload for connectivity testing."""
        response = struct.pack('!BBHi', PROTOCOL_VERSION, 0x00, self.MSG_ECHO, len(payload))
        response += payload
        response += self._compute_mac(response)
        return response

    def _handle_retrieve(self, payload: bytes) -> bytes:
        """Retrieve a stored message by ID."""
        if len(payload) < 2:
            return self._error_response('invalid_retrieve_request')

        msg_id = struct.unpack('!H', payload[:2])[0]
        data = self._store.get_message(msg_id)

        if data is None:
            return self._error_response('not_found')

        response = struct.pack('!BBHi', PROTOCOL_VERSION, 0x00, self.MSG_RETRIEVE, len(data))
        response += data
        response += self._compute_mac(response)
        return response

    def _handle_store(self, payload: bytes) -> bytes:
        """Store a message with given ID."""
        if len(payload) < 4:
            return self._error_response('invalid_store_request')

        msg_id = struct.unpack('!H', payload[:2])[0]
        data = payload[2:]

        if self._store.store_message(msg_id, data):
            return self._success_response()
        return self._error_response('store_failed')

    def _error_response(self, error: str) -> bytes:
        err_bytes = error.encode('utf-8')
        response = struct.pack('!BBHi', PROTOCOL_VERSION, 0x80, 0x00, len(err_bytes))
        response += err_bytes
        response += self._compute_mac(response)
        return response

    def _success_response(self) -> bytes:
        response = struct.pack('!BBHi', PROTOCOL_VERSION, 0x00, 0x00, 0)
        response += self._compute_mac(response)
        return response

    def process_message(self, buffer: bytes) -> Optional[bytes]:
        """Process an incoming protocol message."""
        if len(buffer) < self.HEADER_SIZE + self.MAC_SIZE:
            return self._error_response('message_too_short')

        # Parse header
        header = buffer[:self.HEADER_SIZE]
        valid, header_info = self._validate_header(header)

        if not valid:
            return self._error_response(header_info.get('error', 'invalid_header'))

        # Extract and verify payload
        payload = self._extract_payload(buffer, header_info)
        if payload is None:
            return self._error_response('incomplete_message')

        # Verify MAC over header + payload
        payload_len = header_info['payload_len']
        message_data = buffer[:self.HEADER_SIZE + payload_len]
        provided_mac = buffer[self.HEADER_SIZE + payload_len:self.HEADER_SIZE + payload_len + self.MAC_SIZE]

        if len(provided_mac) != self.MAC_SIZE:
            return self._error_response('invalid_mac_length')

        if not self._verify_mac(message_data, provided_mac):
            return self._error_response('authentication_failed')

        # Dispatch based on message type
        msg_type = header_info['msg_type']

        if msg_type == self.MSG_ECHO:
            return self._handle_echo(payload)
        elif msg_type == self.MSG_RETRIEVE:
            return self._handle_retrieve(payload)
        elif msg_type == self.MSG_STORE:
            return self._handle_store(payload)
        elif msg_type == self.MSG_LIST:
            return self._error_response('not_implemented')

        return self._error_response('unknown_type')


class ProtocolServer:
    """TCP server for the binary protocol."""

    def __init__(self, host: str = '127.0.0.1', port: int = 9999):
        self._host = host
        self._port = port
        self._handler = ProtocolHandler(SECRET_KEY)
        self._running = False

    def _handle_client(self, conn: socket.socket, addr: tuple):
        """Handle a single client connection."""
        try:
            conn.settimeout(30.0)
            buffer = b''

            while True:
                data = conn.recv(4096)
                if not data:
                    break

                buffer += data

                if len(buffer) >= ProtocolHandler.HEADER_SIZE:
                    response = self._handler.process_message(buffer)
                    if response:
                        conn.sendall(response)
                    buffer = b''
        except (socket.timeout, ConnectionResetError, BrokenPipeError):
            pass
        finally:
            conn.close()

    def start(self):
        """Start the protocol server."""
        self._running = True
        server_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_sock.bind((self._host, self._port))
        server_sock.listen(5)

        while self._running:
            conn, addr = server_sock.accept()
            thread = threading.Thread(target=self._handle_client, args=(conn, addr))
            thread.daemon = True
            thread.start()


if __name__ == '__main__':
    server = ProtocolServer()
    server.start()
